append.source:
import {useRef, useState} from 'react';

const makeRows = start => [{id: start}];

function Row({item}) {
  return (
    <li>
      <span>{item.id}</span>
      <strong>Item {item.id}</strong>
    </li>
  );
}

function List({items}) {
  return <ul>{items.map(item => <Row key={item.id} item={item} />)}</ul>;
}

function App() {
  const [items, setItems] = useState([]);
  const addButtonRef = useRef(null);

  async function add2000Rows() {
    const button = addButtonRef.current;
    if (button === null) return;
    for (let i = 0; i < 2000; i++) {
      button.click();
      await null;
    }
  }

  return (
    <main>
      <button ref={addButtonRef} onClick={
          () => setItems(items => [...items, ...makeRows(items.length)])}>
        Add one row
      </button>
      <button id="run-2000" onClick={add2000Rows}>
        Add 2,000 rows one at a time
      </button>
      <List items={items} />
    </main>
  );
}

