selection.source:
import {useState} from 'react';
const items = Array.from({length:2000}, (_,id) => ({id}));
function App() {
  const [selectedId, setSelectedId] = useState(-1);
  async function run() {
    for (let id=0; id<200; id++) {
      document.getElementById('row-'+id).click();
      await null;
    }
  }
  return <main><button id="run" onClick={run}>Select 200 rows</button><ul>{items.map(item =>
    <li id={'row-'+item.id} key={item.id} className={item.id === selectedId ? 'selected' : ''}
      onClick={() => setSelectedId(item.id)}><span>{item.id}</span><strong>Item {item.id}</strong></li>
  )}</ul></main>;
}

