context.source:
import {createContext, useContext, useState} from 'react';
const ChatContext = createContext({currentUserId:0, typingUsers:0, unreadCount:0});
const messages = Array.from({length:2000}, (_,id) => ({id, authorId:id%5, text:'Message '+id}));
function Message({message}) {
  const chat = useContext(ChatContext);
  const isMine = message.authorId === chat.currentUserId;
  return <li className={isMine ? 'mine' : ''}>{message.text}</li>;
}
function MessageList({messages}) { return <ul>{messages.map(m => <Message key={m.id} message={m} />)}</ul>; }
function App() {
  const [typingUsers, setTypingUsers] = useState(0);
  async function run() {
    for (let i=0; i<200; i++) { document.getElementById('typing').click(); await null; }
  }
  return <ChatContext.Provider value={{currentUserId:0, typingUsers, unreadCount:0}}>
    <button id="typing" onClick={() => setTypingUsers(n => n+1)}>Someone is typing</button>
    <button id="run" onClick={run}>Send 200 typing updates</button><p>Typing: {typingUsers}</p>
    <MessageList messages={messages} />
  </ChatContext.Provider>;
}

