store.source:
import {create} from 'zustand';
const useCardStore = create(set => ({selectedId:null, select:id => set({selectedId:id})}));
const ids = Array.from({length:2000}, (_,id) => id);
function Card({id}) {
  const selectedId = useCardStore(state => state.selectedId);
  const select = useCardStore(state => state.select);
  const isSelected = id === selectedId;
  return <li id={'row-'+id} className={isSelected ? 'selected' : ''} onClick={() => select(id)}>Card {id}</li>;
}
function App() {
  async function run() {
    for (let id=0; id<200; id++) { document.getElementById('row-'+id).click(); await null; }
  }
  return <main><button id="run" onClick={run}>Select 200 cards</button><ul>{ids.map(id => <Card key={id} id={id} />)}</ul></main>;
}

